def rotate(rotator, base):
    return base[-1] + base[:-1]

def solve(input):
    groups = {}
    for i in input:
        new = rotate(i, i)
        if new in groups:
            groups[new].append(i)
        else:
            groups[new] = [i]
    ret = []
    for key in sorted(groups, key=len, reverse=True):
        if len(groups[key]) == 1:
            ret.append(groups[key][0])
        else:
            temp = sorted(groups[key], key=lambda x: x.upper())
            for i in range(1, len(temp)):
                if temp[i].lower() == temp[0].lower():
                    ret.append(temp[i])
                    break
    return sorted(ret, key=lambda x: (len(x), x))
